/
{
reset0: reset@20000004 {
compatible = "reset-mmio";
reg = <0x20000004 0x4>;
num-resets = <16>;
};

reset1: reset@20000008 {
compatible = "reset-mmio";
reg = <0x20000008 0x4>;
num-resets = <16>;
active-low;
};
};

#include <zephyr/drivers/reset.h>
#include <zephyr/drivers/gpio.h> // Often reset controllers are tied to GPIOs or simple MMIO
#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/sys/sys_io.h>

#define DT_DRV_COMPAT reset_mmio

struct reset_mmio_config {
	mm_reg_t base;
	uint32_t num_resets;
};

struct reset_mmio_data {
	/* No runtime data needed for this simple driver */
};

static int reset_mmio_assert(const struct device *dev, uint32_t id)
{
	const struct reset_mmio_config *config = dev->config;

	if (id >= config->num_resets) {
		return -EINVAL;
	}

	sys_set_bit(config->base, id);
	return 0;
}

static int reset_mmio_deassert(const struct device *dev, uint32_t id)
{
	const struct reset_mmio_config *config = dev->config;

	if (id >= config->num_resets) {
		return -EINVAL;
	}

	sys_clear_bit(config->base, id);
	return 0;
}

static int reset_mmio_status(const struct device *dev, uint32_t id, uint8_t *state)
{
	const struct reset_mmio_config *config = dev->config;

	if (id >= config->num_resets) {
		return -EINVAL;
	}

	*state = sys_test_bit(config->base, id);
	return 0;
}

static const struct reset_driver_api reset_mmio_driver_api = {
	.line_assert = reset_mmio_assert,
	.line_deassert = reset_mmio_deassert,
	.status = reset_mmio_status,
};

#define RESET_MMIO_INIT(inst) \
	static const struct reset_mmio_config reset_mmio_config_##inst = { \
		.base = DT_REG_ADDR(DT_DRV_INST(inst)), \
		.num_resets = DT_INST_PROP(inst, num_resets), \
	}; \
	static struct reset_mmio_data reset_mmio_data_##inst; \
	DEVICE_DT_INST_DEFINE(inst, NULL, NULL, \
			      &reset_mmio_data_##inst, &reset_mmio_config_##inst, \
			      PRE_KERNEL_1, CONFIG_RESET_INIT_PRIORITY, \
			      &reset_mmio_driver_api);

DT_INST_FOREACH_STATUS_OKAY(RESET_MMIO_INIT)

